#include <filesystem>
namespace fs = std::filesystem;

try {
    // Create a symbolic link to a file:
    fs::create_symlink("target.txt", "link.txt");

    // Create a symbolic link to a directory:
    fs::create_directory_symlink("target_dir", "link_dir");

    // Check if a path is a symlink:
    if (fs::is_symlink("link.txt")) {
        cout << "It's a symlink\n";

        // Resolve the symlink:
        fs::path target = fs::read_symlink("link.txt");
        cout << "Points to: " << target << '\n';

        // Get the canonical (absolute, no symlinks) path:
        fs::path canon = fs::canonical(target);
        cout << "Canonical: " << canon << '\n';
    }

    // Copy symlinks (not their targets):
    fs::copy("link.txt", "link_copy.txt",
             fs::copy_options::copy_symlinks);

} catch (const fs::filesystem_error& e) {
    // Symlinks may require special permissions on some systems
    cerr << "Error: " << e.what() << '\n';
}

